<template><section class="care-coverage" aria-label="Coverage and billing follow-up"><h4>Insurance &amp; payment setup</h4><p v-if="loading" role="status">Loading coverage and payment setup…</p><p v-if="error" role="alert">{{ error }}</p><template v-if="summary"><p v-for="policy in summary.policies || []" :key="policy.position">{{ policy.position === 'primary' ? 'Primary' : 'Secondary' }}: {{ policy.insurerName }}</p><p v-if="!summary.policies?.length">Insurance not yet recorded.</p><ClientPaymentSetupSummary :setup="summary.paymentSetup || null" /></template><button type="button" :disabled="loading" @click="load">Refresh coverage and status</button></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import api from '../../services/api.js';
import ClientPaymentSetupSummary from './ClientPaymentSetupSummary.vue';
const props=defineProps({clientId:[String,Number]});const summary=ref(null),loading=ref(false),error=ref('');let generation=0;
async function load(){const current=++generation;summary.value=null;error.value='';loading.value=false;if(!Number(props.clientId))return;loading.value=true;try{const r=await api.get(`/clients/${props.clientId}/care-billing-summary`,{skipGlobalLoading:true});if(current===generation)summary.value=r.data;}catch{if(current===generation)error.value='Coverage and payment setup could not be loaded.';}finally{if(current===generation)loading.value=false;}}
watch(()=>props.clientId,load,{immediate:true});onBeforeUnmount(()=>generation++);
</script>
<style scoped>.care-coverage{padding:18px;border:1px solid var(--border,#dce4ee);border-radius:12px;margin:12px 0}.care-coverage h4{margin:0 0 14px}.care-coverage p{line-height:1.5}.care-coverage>button{display:block;margin-top:16px;padding:9px 13px;border:1px solid #b8c9db;border-radius:7px;background:var(--bg-card,#fff);color:var(--primary-color,#1555b0);font:inherit;cursor:pointer}.care-coverage [role=alert]{color:var(--app-text-red,#a32121)}</style>
